original_prompt:
{
  "Use the attached image of the person as reference. Hyper-realistic black and white studio portrait of the young man in side profile, natural hair gently falling around his face. Strong rim light accentuating his jawline and nose, dark minimalist background. Expression thoughtful and serene, cinematic lighting creating dramatic contrast and fine photographic detail.",
  "size": "{argument name="image size" default="1024x1024"}",
  "n": {argument name="number of images" default="1"}
}

vi_prompt:
{
  "Sử dụng hình ảnh đính kèm của người này làm tài liệu tham khảo. Ảnh chân dung studio đen trắng siêu thực của một chàng trai trẻ ở góc nhìn nghiêng (side profile), mái tóc tự nhiên buông lơi nhẹ nhàng quanh khuôn mặt. Ánh sáng viền (rim light) mạnh mẽ làm nổi bật đường viền xương hàm và sống mũi, nền tối giản gam màu tối. Biểu cảm trầm ngâm và thanh thản, ánh sáng điện ảnh tạo độ tương phản ấn tượng và chi tiết nhiếp ảnh sắc nét.",
  "size": "{argument name="kích thước ảnh" default="1024x1024"}",
  "n": {argument name="số lượng ảnh" default="1"}
}
